/*!50001 VIEW `vendor_master` AS with `vendor_rev` as (select `p`.`vendor_id` AS `vendor_id`,coalesce(sum((`oi`.`quantity` * `oi`.`item_price`)),0) AS `revenue_generated`,concat(convert(date_format(min(`o`.`order_date`),'%b-%Y') using utf8mb4),' - ',convert(date_format(max(`o`.`order_date`),'%b-%Y') using utf8mb4)) AS `revenue_period` from ((`orders` `o` join `order_items` `oi` on(((`o`.`order_id` = `oi`.`order_id`) and (`o`.`status` = 'Completed')))) join `products` `p` on((`oi`.`product_id` = `p`.`product_id`))) group by `p`.`vendor_id`), `vendor_pyt` as (select `v`.`vendor_id` AS `vendor_id`,`v`.`vendor_name` AS `vendor_name`,max(`v`.`commission_rate`) AS `commission_rate`,coalesce(sum(`vp`.`payout_amount`),0) AS `total_payout_amount`,concat(convert(date_format(min(`vp`.`payout_date`),'%b-%Y') using utf8mb4),' - ',convert(date_format(max(`vp`.`payout_date`),'%b-%Y') using utf8mb4)) AS `payout_period` from (`vendors` `v` left join `vendor_payouts` `vp` on(((`v`.`vendor_id` = `vp`.`vendor_id`) and (`v`.`status` <> 'Suspended')))) group by `v`.`vendor_id`,`v`.`vendor_name`) select `vp`.`vendor_id` AS `vendor_id`,`vp`.`vendor_name` AS `vendor_name`,`vp`.`commission_rate` AS `commission_rate`,`vp`.`total_payout_amount` AS `total_payout_amount`,`vp`.`payout_period` AS `payout_period`,`vr`.`revenue_period` AS `revenue_period`,`vr`.`revenue_generated` AS `revenue_generated`,round((`vr`.`revenue_generated` * (1 - (`vp`.`commission_rate` / 100))),2) AS `expected_payout`,(round((`vr`.`revenue_generated` * (1 - (`vp`.`commission_rate` / 100))),2) - `vp`.`total_payout_amount`) AS `remaining` from (`vendor_pyt` `vp` left join `vendor_rev` `vr` on((`vp`.`vendor_id` = `vr`.`vendor_id`))) */;
